SELECT gen_random_uuid()::text, 'formula', '$P = x\dot m(h_s - h_{ex})\eta_t\eta_g$', 'Geothermal Plant Output', '$P = x\,\dot m\,(h_g - h_{ex})\,\eta_t\,\eta_g$', '$\text{kW}$', 'Power from a single-flash geothermal plant.', '[{"symbol":"$x$","meaning":"flash fraction","unit":null},{"symbol":"$\\dot m$","meaning":"well flow","unit":"$\\text{kg/s}$"},{"symbol":"$h_g, h_{ex}$","meaning":"turbine inlet and exhaust enthalpies","unit":"$\\text{kJ/kg}$"},{"symbol":"$\\eta_t, \\eta_g$","meaning":"turbine and generator efficiencies","unit":null}]'::jsonb, 'Most of the well flow returns as brine; a second flash recovers more.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'geothermal plants' AND s."active"), NULL, false, 'PENDING', now(), now()
