SELECT gen_random_uuid()::text, 'formula', '$P = P_{STC}[1 + \gamma(T_c - 25)]$', 'PV Temperature Derating', '$P = P_{STC}\frac{G}{1000}[1 + \gamma(T_c - 25)],\qquad T_c = T_a + \frac{\text{NOCT} - 20}{800}G$', '$\text{W}$', 'A module''s output at real irradiance and cell temperature, from its STC rating.', '[{"symbol":"$\\gamma$","meaning":"power temperature coefficient, about −0.004 per °C","unit":null},{"symbol":"$T_c, T_a$","meaning":"cell and ambient temperature","unit":"$\\text{°C}$"},{"symbol":"$G$","meaning":"irradiance","unit":"$\\text{W/m}^2$"},{"symbol":"$\\text{NOCT}$","meaning":"nominal operating cell temperature","unit":"$\\text{°C}$"}]'::jsonb, 'In the tropics cells run 50–60 °C: 10–15% below the nameplate even in full sun.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'solar pv' AND s."active"), NULL, false, 'PENDING', now(), now()
