SELECT gen_random_uuid()::text, 'formula', '$P_{array} = \frac{E}{\text{PSH} \times \eta_{sys}}$', 'PV Array Size from Peak Sun Hours', '$P_{array} = \frac{E_{daily}}{\text{PSH} \times \eta_{sys}},\qquad N = \frac{P_{array}}{P_{module}}$', '$\text{kW}$', 'The array rating needed to supply a daily energy.', '[{"symbol":"$E_{daily}$","meaning":"daily energy needed","unit":"$\\text{kWh}$"},{"symbol":"$\\text{PSH}$","meaning":"peak sun hours (kWh/m²/day)","unit":"$\\text{h}$"},{"symbol":"$\\eta_{sys}$","meaning":"system derate: temperature, wiring, inverter, soiling (≈ 0.75–0.8)","unit":null}]'::jsonb, 'Philippine sites typically get 4.5–5.5 peak sun hours. Round module count up.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'solar pv' AND s."active"), NULL, false, 'PENDING', now(), now()
