SELECT gen_random_uuid()::text, 'formula', '$C = \frac{E\,D}{V\cdot\text{DoD}\cdot\eta}$', 'Battery Bank Capacity', '$C = \frac{E_{daily}\,D}{V_{bank}\cdot\text{DoD}\cdot\eta_{batt}}\ (\text{Ah})$', '$\text{Ah}$', 'Ampere-hours of storage for a load over a number of sunless days.', '[{"symbol":"$E_{daily}$","meaning":"daily load","unit":"$\\text{Wh}$"},{"symbol":"$D$","meaning":"days of autonomy","unit":null},{"symbol":"$V_{bank}$","meaning":"bank voltage","unit":"$\\text{V}$"},{"symbol":"$\\text{DoD}$","meaning":"allowed depth of discharge (0.5 lead-acid, 0.8–0.9 lithium)","unit":null}]'::jsonb, 'Shallow discharge greatly extends lead-acid life.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'solar pv' AND s."active"), NULL, false, 'PENDING', now(), now()
