SELECT gen_random_uuid()::text, 'formula', '$C_{p,\max} = \frac{16}{27}$', 'Betz Limit', '$C_p = 4a(1 - a)^2,\qquad C_{p,\max} = \frac{16}{27} = 0.593\ (a = \tfrac13)$', NULL, 'No turbine can capture more than 59.3% of the wind''s kinetic power.', '[{"symbol":"$a$","meaning":"axial induction factor (fractional slowing of the wind at the rotor)","unit":null},{"symbol":"$C_p$","meaning":"power coefficient","unit":null}]'::jsonb, 'Real turbines reach about 0.45–0.50.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'wind' AND s."active"), NULL, true, 'PENDING', now(), now()
