SELECT gen_random_uuid()::text, 'formula', '$v_2 = v_1\left(\frac{h_2}{h_1}\right)^\alpha$', 'Wind Shear Power Law', '$v_2 = v_1\left(\frac{h_2}{h_1}\right)^{\alpha},\qquad \alpha \approx \tfrac17\ (\text{open terrain})$', '$\text{m/s}$', 'Wind speed at hub height from a measurement lower down.', '[{"symbol":"$v_1$","meaning":"wind speed measured at height h₁","unit":"$\\text{m/s}$"},{"symbol":"$h_1, h_2$","meaning":"measurement and hub heights","unit":"$\\text{m}$"},{"symbol":"$\\alpha$","meaning":"shear exponent","unit":null}]'::jsonb, 'Power goes as v³: 10% more wind speed is 33% more power.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'wind' AND s."active"), NULL, false, 'PENDING', now(), now()
