SELECT gen_random_uuid()::text, 'formula', '$P = \frac{\dot m_f\,\text{HV}\,\eta}{3600}$', 'Biomass Plant Output', '$P = \frac{\dot m_f\,\text{HV}\,\eta}{3600}\ \text{kW}\quad (\dot m_f \text{ in kg/h, HV in kJ/kg})$', '$\text{kW}$', 'Electrical output from a fuel feed rate (bagasse, rice husk, wood).', '[{"symbol":"$\\dot m_f$","meaning":"fuel feed","unit":"$\\text{kg/h}$"},{"symbol":"$\\text{HV}$","meaning":"heating value as fired","unit":"$\\text{kJ/kg}$"},{"symbol":"$\\eta$","meaning":"overall efficiency","unit":null}]'::jsonb, 'Use the AS-FIRED (wet) heating value; dry-basis values overstate output.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'biomass' AND s."active"), NULL, false, 'PENDING', now(), now()
