SELECT gen_random_uuid()::text, 'formula', '$c = \frac{C_{cap}\text{CRF} + C_{O\&M} + C_{fuel}}{E}$', 'Generation Cost per kWh', '$c = \frac{C_{cap}\,\text{CRF} + C_{O\&M} + C_{fuel}}{E},\qquad \text{CRF} = \frac{i(1 + i)^n}{(1 + i)^n - 1}$', '$\text{₱/kWh}$', 'The cost of each kWh: annualized capital plus running costs over the energy produced.', '[{"symbol":"$C_{cap}$","meaning":"capital cost","unit":"$\\text{₱}$"},{"symbol":"$\\text{CRF}$","meaning":"capital recovery factor","unit":null},{"symbol":"$C_{O\\&M}, C_{fuel}$","meaning":"annual operating and fuel costs","unit":"$\\text{₱/yr}$"},{"symbol":"$E$","meaning":"annual energy","unit":"$\\text{kWh}$"}]'::jsonb, 'Fixed costs per kWh fall as the capacity factor rises: base-load plants need high CF.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'plant economics' AND s."active"), NULL, false, 'PENDING', now(), now()
