SELECT gen_random_uuid()::text, 'formula', '$C = a\,P_{\max} + b\,E$', 'Two-Part Tariff', '$C = a\,P_{\max} + b\,E\quad (\text{Hopkinson})$', '$\text{₱}$', 'A bill in two parts: one for the capacity reserved (demand), one for the energy used.', '[{"symbol":"$a$","meaning":"demand charge","unit":"$\\text{₱/kW}$"},{"symbol":"$b$","meaning":"energy charge","unit":"$\\text{₱/kWh}$"},{"symbol":"$P_{\\max}$","meaning":"maximum demand","unit":"$\\text{kW}$"},{"symbol":"$E$","meaning":"energy used","unit":"$\\text{kWh}$"}]'::jsonb, 'A higher load factor spreads the demand charge over more kWh, lowering the average rate.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'plant economics' AND s."active"), NULL, false, 'PENDING', now(), now()
