SELECT gen_random_uuid()::text, 'formula', '$h = \frac{F_1 - F_2}{v_2 - v_1}$', 'Break-Even Operating Hours', '$h^* = \frac{F_1 - F_2}{v_2 - v_1}\quad (\text{per kW: fixed } F,\ \text{variable } v)$', '$\text{h/yr}$', 'The yearly running hours above which the high-capital, low-fuel plant is cheaper.', '[{"symbol":"$F_1, F_2$","meaning":"annual fixed cost per kW of the two plant types","unit":"$\\text{₱/kW·yr}$"},{"symbol":"$v_1, v_2$","meaning":"variable cost per kWh","unit":"$\\text{₱/kWh}$"}]'::jsonb, 'Below h* use peaking plant (low capital, high fuel); above it, base-load plant.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'plant economics' AND s."active"), NULL, false, 'PENDING', now(), now()
