SELECT gen_random_uuid()::text, 'formula', '$P = \frac{\rho gQH}{\eta},\ \frac{Q\Delta p}{\eta}$', 'Auxiliary Pump and Fan Power', '$P_{pump} = \frac{\rho gQH}{\eta},\qquad P_{fan} = \frac{Q\,\Delta p}{\eta}$', '$\text{W}$', 'Input power of the plant''s largest auxiliaries: feed and cooling pumps, draft fans.', '[{"symbol":"$Q$","meaning":"flow","unit":"$\\text{m}^3/\\text{s}$"},{"symbol":"$H$","meaning":"pump head","unit":"$\\text{m}$"},{"symbol":"$\\Delta p$","meaning":"fan pressure rise","unit":"$\\text{Pa}$"},{"symbol":"$\\eta$","meaning":"overall efficiency (machine × motor)","unit":null}]'::jsonb, 'The boiler feed pump is often the largest auxiliary load in a steam plant.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'plant auxiliaries' AND s."active"), NULL, false, 'PENDING', now(), now()
