SELECT gen_random_uuid()::text, 'formula', '$P_{net} = P_{gross} - P_{aux}$', 'Net Plant Output and Station Service', '$P_{net} = P_{gross} - P_{aux},\qquad \text{HR}_{net} = \text{HR}_{gross}\frac{P_{gross}}{P_{net}}$', '$\text{kW}$', 'What the plant actually sends out after feeding its own auxiliaries.', '[{"symbol":"$P_{gross}$","meaning":"generator output","unit":"$\\text{kW}$"},{"symbol":"$P_{aux}$","meaning":"station service (auxiliary) load","unit":"$\\text{kW}$"},{"symbol":"$\\text{HR}$","meaning":"heat rate","unit":"$\\text{kJ/kWh}$"}]'::jsonb, 'Steam plants use about 5–10% for auxiliaries; hydro about 1%.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power Plant Engineering' AND t."subject" = 'EE' AND s."normKey" = 'plant auxiliaries' AND s."active"), NULL, false, 'PENDING', now(), now()
